fn solve(n: usize, s: Vec<char>) -> Vec<char> {
    // Counters for "S"->"F" and "F"->"S" transitions
    let mut count_sf = 0;
    let mut count_fs = 0;

    // Iterate over adjacent pairs
    for i in 1..n {
        match (s[i - 1], s[i]) {
            ('S', 'F') => count_sf += 1,
            ('F', 'S') => count_fs += 1,
            _ => {}
        }
    }

    // Return "YES" if count_sf > count_fs, otherwise "NO"
    if count_sf > count_fs {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

